package gitops

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// CanonicalURL normalizes a Git remote URL into a canonical form:
// - Strips trailing .git and trailing slashes
// - Converts SSH/scp-like syntax (git@host:owner/repo) to https://host/owner/repo
// - Normalizes schemes (ssh://, git://) to https://
// - Lowercases the host component
func CanonicalURL(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	raw = strings.TrimSuffix(raw, "/")
	raw = strings.TrimSuffix(raw, ".git")

	// Match scp style: [user@]host:path
	if !strings.Contains(raw, "://") && strings.Contains(raw, ":") {
		parts := strings.SplitN(raw, ":", 2)
		hostPart := parts[0]
		pathPart := parts[1]
		if atIdx := strings.Index(hostPart, "@"); atIdx != -1 {
			hostPart = hostPart[atIdx+1:]
		}
		hostPart = strings.ToLower(hostPart)
		pathPart = strings.TrimPrefix(pathPart, "/")
		pathPart = strings.TrimSuffix(pathPart, "/")
		pathPart = strings.TrimSuffix(pathPart, ".git")
		return "https://" + hostPart + "/" + pathPart
	}

	// Match URL scheme: scheme://[user@]host[:port]/path
	if u, err := url.Parse(raw); err == nil && u.Host != "" {
		host := strings.ToLower(u.Hostname())
		path := strings.TrimPrefix(u.Path, "/")
		path = strings.TrimSuffix(path, "/")
		path = strings.TrimSuffix(path, ".git")
		return "https://" + host + "/" + path
	}

	return raw
}

// ComputeRepoID hashes the root commit and remote URL/worktree real path using SHA-256:
// sha256(root commit + ":" + canonical origin URL or real path)
func ComputeRepoID(rootCommit, remoteOrPath string) string {
	sum := sha256.Sum256([]byte(rootCommit + ":" + remoteOrPath))
	return hex.EncodeToString(sum[:])
}

// GetRootCommit returns the oldest root commit hash in the repository.
func GetRootCommit(repoRoot string) (string, error) {
	cmd := exec.Command("git", "-C", repoRoot, "rev-list", "--max-parents=0", "--reverse", "HEAD")
	output, err := cmd.Output()
	if err != nil {
		return "", err
	}
	lines := strings.Split(strings.TrimSpace(string(output)), "\n")
	if len(lines) == 0 || lines[0] == "" {
		return "", errors.New("no root commit found")
	}
	return strings.TrimSpace(lines[0]), nil
}

// GetCanonicalOriginURL returns the normalized origin remote URL if one exists.
func GetCanonicalOriginURL(repoRoot string) (string, error) {
	cmd := exec.Command("git", "-C", repoRoot, "config", "--get", "remote.origin.url")
	output, err := cmd.Output()
	if err != nil || len(strings.TrimSpace(string(output))) == 0 {
		// Fallback to git remote get-url origin
		cmd2 := exec.Command("git", "-C", repoRoot, "remote", "get-url", "origin")
		output2, err2 := cmd2.Output()
		if err2 != nil || len(strings.TrimSpace(string(output2))) == 0 {
			return "", nil
		}
		output = output2
	}

	canonical := CanonicalURL(strings.TrimSpace(string(output)))
	return canonical, nil
}

// GetMainWorktreePath resolves the real filesystem path of the main worktree.
func GetMainWorktreePath(repoRoot string) (string, error) {
	cmd := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain")
	if output, err := cmd.Output(); err == nil {
		lines := strings.Split(string(output), "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if strings.HasPrefix(line, "worktree ") {
				p := strings.TrimPrefix(line, "worktree ")
				if real, err := filepath.EvalSymlinks(p); err == nil {
					return real, nil
				}
				return filepath.Clean(p), nil
			}
		}
	}

	// Fallback to show-toplevel
	cmdTop := exec.Command("git", "-C", repoRoot, "rev-parse", "--show-toplevel")
	if output, err := cmdTop.Output(); err == nil {
		p := strings.TrimSpace(string(output))
		if real, err := filepath.EvalSymlinks(p); err == nil {
			return real, nil
		}
		return filepath.Clean(p), nil
	}

	if real, err := filepath.EvalSymlinks(repoRoot); err == nil {
		return real, nil
	}
	return filepath.Clean(repoRoot), nil
}

// GetWorktreePaths returns all active worktree paths for the git repository.
func GetWorktreePaths(repoRoot string) ([]string, error) {
	cmd := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain")
	output, err := cmd.Output()
	if err != nil {
		// Not a git worktree or error; return repoRoot
		return []string{repoRoot}, nil
	}

	var paths []string
	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "worktree ") {
			p := strings.TrimPrefix(line, "worktree ")
			if real, err := filepath.EvalSymlinks(p); err == nil {
				paths = append(paths, real)
			} else {
				paths = append(paths, filepath.Clean(p))
			}
		}
	}
	if len(paths) == 0 {
		paths = append(paths, repoRoot)
	}
	return paths, nil
}

// FindRepoRoot determines the root directory of the repository containing startDir.
func FindRepoRoot(startDir string) (string, error) {
	if startDir == "" {
		startDir = "."
	}
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return startDir, err
	}

	cmd := exec.Command("git", "-C", abs, "rev-parse", "--show-toplevel")
	if output, err := cmd.Output(); err == nil {
		p := strings.TrimSpace(string(output))
		return filepath.Clean(p), nil
	}

	// Walk upwards looking for .git or .memory directory
	curr := abs
	for {
		if _, err := os.Stat(filepath.Join(curr, ".git")); err == nil {
			return curr, nil
		}
		if _, err := os.Stat(filepath.Join(curr, ".memory")); err == nil {
			return curr, nil
		}
		parent := filepath.Dir(curr)
		if parent == curr {
			break
		}
		curr = parent
	}

	return abs, nil
}

// GenerateRepoID generates the canonical Repo ID for the repository:
// sha256(root commit + ":" + canonical origin URL), falling back to main worktree real path if no remote URL exists.
func GenerateRepoID(repoRoot string) (string, error) {
	rootCommit, err := GetRootCommit(repoRoot)
	if err != nil {
		// If git repo has no commits yet or git command fails, use empty root commit
		rootCommit = ""
	}

	originURL, err := GetCanonicalOriginURL(repoRoot)
	if err == nil && originURL != "" {
		return ComputeRepoID(rootCommit, originURL), nil
	}

	mainWorktree, err := GetMainWorktreePath(repoRoot)
	if err != nil {
		mainWorktree = repoRoot
	}
	if real, err := filepath.EvalSymlinks(mainWorktree); err == nil {
		mainWorktree = real
	}
	return ComputeRepoID(rootCommit, mainWorktree), nil
}

package gitops

import (
	"crypto/sha256"
	"encoding/hex"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

func TestCanonicalURL(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "ssh scp style with git extension",
			input:    "git@github.com:cblabs-org/repo-memory-plugin.git",
			expected: "https://github.com/cblabs-org/repo-memory-plugin",
		},
		{
			name:     "https with git extension and trailing slash",
			input:    "https://github.com/cblabs-org/repo-memory-plugin.git/",
			expected: "https://github.com/cblabs-org/repo-memory-plugin",
		},
		{
			name:     "ssh url scheme",
			input:    "ssh://git@github.com/cblabs-org/repo-memory-plugin.git",
			expected: "https://github.com/cblabs-org/repo-memory-plugin",
		},
		{
			name:     "uppercase host",
			input:    "https://GITHUB.COM/cblabs-org/repo-memory-plugin.git",
			expected: "https://github.com/cblabs-org/repo-memory-plugin",
		},
		{
			name:     "gitlab subgroup",
			input:    "git@gitlab.com:group/subgroup/project.git",
			expected: "https://gitlab.com/group/subgroup/project",
		},
		{
			name:     "empty string",
			input:    "",
			expected: "",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := CanonicalURL(tc.input)
			if got != tc.expected {
				t.Errorf("CanonicalURL(%q) = %q; want %q", tc.input, got, tc.expected)
			}
		})
	}
}

func TestComputeRepoID(t *testing.T) {
	rootCommit := "abc1234567890abcdef1234567890abcdef1234"
	remoteURL := "https://github.com/cblabs-org/repo-memory-plugin"

	expectedSum := sha256.Sum256([]byte(rootCommit + ":" + remoteURL))
	expected := hex.EncodeToString(expectedSum[:])

	got := ComputeRepoID(rootCommit, remoteURL)
	if got != expected {
		t.Errorf("ComputeRepoID() = %q; want %q", got, expected)
	}
}

func runGitCmd(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(),
		"GIT_AUTHOR_NAME=Test User",
		"GIT_AUTHOR_EMAIL=test@example.com",
		"GIT_COMMITTER_NAME=Test User",
		"GIT_COMMITTER_EMAIL=test@example.com",
	)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git command failed (%v): %s", err, string(out))
	}
}

func TestGenerateRepoID_WithRemote(t *testing.T) {
	tmp := t.TempDir()

	runGitCmd(t, tmp, "init")
	runGitCmd(t, tmp, "config", "user.name", "Test User")
	runGitCmd(t, tmp, "config", "user.email", "test@example.com")
	runGitCmd(t, tmp, "commit", "--allow-empty", "-m", "initial root commit")
	runGitCmd(t, tmp, "remote", "add", "origin", "git@github.com:cblabs-org/repo-memory-plugin.git")

	rootCommit, err := GetRootCommit(tmp)
	if err != nil {
		t.Fatalf("GetRootCommit failed: %v", err)
	}
	if len(rootCommit) != 40 {
		t.Errorf("expected 40-char commit hash, got %q", rootCommit)
	}

	repoID, err := GenerateRepoID(tmp)
	if err != nil {
		t.Fatalf("GenerateRepoID failed: %v", err)
	}

	expectedID := ComputeRepoID(rootCommit, "https://github.com/cblabs-org/repo-memory-plugin")
	if repoID != expectedID {
		t.Errorf("GenerateRepoID() = %q; want %q", repoID, expectedID)
	}

	// Make another commit, ensure root commit remains identical and repoID remains stable
	runGitCmd(t, tmp, "commit", "--allow-empty", "-m", "second commit")
	repoID2, err := GenerateRepoID(tmp)
	if err != nil {
		t.Fatalf("second GenerateRepoID failed: %v", err)
	}
	if repoID2 != repoID {
		t.Errorf("RepoID changed after second commit: got %q, want %q", repoID2, repoID)
	}
}

func TestGenerateRepoID_NoRemote(t *testing.T) {
	tmp := t.TempDir()

	runGitCmd(t, tmp, "init")
	runGitCmd(t, tmp, "config", "user.name", "Test User")
	runGitCmd(t, tmp, "config", "user.email", "test@example.com")
	runGitCmd(t, tmp, "commit", "--allow-empty", "-m", "initial root commit")

	rootCommit, err := GetRootCommit(tmp)
	if err != nil {
		t.Fatalf("GetRootCommit failed: %v", err)
	}

	realTmp, err := filepath.EvalSymlinks(tmp)
	if err != nil {
		realTmp = tmp
	}

	repoID, err := GenerateRepoID(tmp)
	if err != nil {
		t.Fatalf("GenerateRepoID failed: %v", err)
	}

	expectedID := ComputeRepoID(rootCommit, realTmp)
	if repoID != expectedID {
		t.Errorf("GenerateRepoID without remote = %q; want %q", repoID, expectedID)
	}
}

func TestFindRepoRoot(t *testing.T) {
	tmp := t.TempDir()
	runGitCmd(t, tmp, "init")

	subDir := filepath.Join(tmp, "a", "b", "c")
	if err := os.MkdirAll(subDir, 0755); err != nil {
		t.Fatal(err)
	}

	root, err := FindRepoRoot(subDir)
	if err != nil {
		t.Fatalf("FindRepoRoot failed: %v", err)
	}

	realTmp, _ := filepath.EvalSymlinks(tmp)
	realRoot, _ := filepath.EvalSymlinks(root)
	if realRoot != realTmp {
		t.Errorf("FindRepoRoot(%q) = %q; want %q", subDir, realRoot, realTmp)
	}
}

package config

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// RegistryEntry represents an enrolled repository entry in <data-dir>/registry.json.
type RegistryEntry struct {
	RepoID   string `json:"repo_id"`
	RootPath string `json:"root_path"`
}

// UnmarshalJSON supports both snake_case (repo_id, root_path) and PascalCase (RepoID, RootPath).
func (e *RegistryEntry) UnmarshalJSON(data []byte) error {
	type Alias RegistryEntry
	var aux struct {
		Alias
		AltRepoID   string `json:"RepoID"`
		AltRootPath string `json:"RootPath"`
	}
	if err := json.Unmarshal(data, &aux); err != nil {
		return err
	}
	*e = RegistryEntry(aux.Alias)
	if e.RepoID == "" && aux.AltRepoID != "" {
		e.RepoID = aux.AltRepoID
	}
	if e.RootPath == "" && aux.AltRootPath != "" {
		e.RootPath = aux.AltRootPath
	}
	return nil
}

// Registry is a map of workspace paths to RegistryEntry.
type Registry map[string]RegistryEntry

// RegistryPath returns the path to registry.json within the given data directory.
func RegistryPath(dataDir string) string {
	if dataDir == "" {
		dataDir = DataDir()
	}
	return filepath.Join(dataDir, "registry.json")
}

// LoadRegistry reads and parses <data-dir>/registry.json.
// If the file does not exist or is empty, an empty Registry is returned without error.
func LoadRegistry(dataDir string) (Registry, error) {
	path := RegistryPath(dataDir)
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return make(Registry), nil
		}
		return nil, fmt.Errorf("reading registry %s: %w", path, err)
	}

	if len(strings.TrimSpace(string(data))) == 0 {
		return make(Registry), nil
	}

	var reg Registry
	if err := json.Unmarshal(data, &reg); err != nil {
		return nil, fmt.Errorf("parsing registry %s: %w", path, err)
	}
	if reg == nil {
		reg = make(Registry)
	}
	return reg, nil
}

// SaveRegistry writes the Registry to <data-dir>/registry.json atomically.
func SaveRegistry(dataDir string, reg Registry) error {
	if dataDir == "" {
		dataDir = DataDir()
	}
	if err := os.MkdirAll(dataDir, 0755); err != nil {
		return fmt.Errorf("creating data directory %s: %w", dataDir, err)
	}

	path := RegistryPath(dataDir)
	data, err := json.MarshalIndent(reg, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling registry: %w", err)
	}

	tmpFile := filepath.Join(dataDir, fmt.Sprintf("registry-%d.tmp", os.Getpid()))
	if err := os.WriteFile(tmpFile, data, 0644); err != nil {
		return fmt.Errorf("writing temporary registry %s: %w", tmpFile, err)
	}

	if err := os.Rename(tmpFile, path); err != nil {
		_ = os.Remove(tmpFile)
		return fmt.Errorf("renaming registry file to %s: %w", path, err)
	}

	return nil
}

// AddToRegistry records workspace paths mapping to the given repoID and rootPath.
func AddToRegistry(dataDir string, workspacePaths []string, repoID, rootPath string) error {
	reg, err := LoadRegistry(dataDir)
	if err != nil {
		return err
	}

	cleanRoot := filepath.Clean(rootPath)
	evalRoot, _ := filepath.EvalSymlinks(cleanRoot)

	entry := RegistryEntry{
		RepoID:   repoID,
		RootPath: cleanRoot,
	}

	// Always ensure root path is registered
	reg[cleanRoot] = entry
	if evalRoot != "" && evalRoot != cleanRoot {
		reg[evalRoot] = entry
	}

	for _, ws := range workspacePaths {
		cleanWs := filepath.Clean(ws)
		reg[cleanWs] = entry
		if evalWs, err := filepath.EvalSymlinks(cleanWs); err == nil && evalWs != cleanWs {
			reg[evalWs] = entry
		}
	}

	return SaveRegistry(dataDir, reg)
}

// RemoveFromRegistry removes any entries matching repoRoot (or its worktrees) from registry.json.
// Returns the list of distinct RepoIDs removed.
func RemoveFromRegistry(dataDir, repoRoot string) ([]string, error) {
	reg, err := LoadRegistry(dataDir)
	if err != nil {
		return nil, err
	}

	cleanRoot := filepath.Clean(repoRoot)
	evalRoot, _ := filepath.EvalSymlinks(cleanRoot)

	var removedIDs []string
	seen := make(map[string]bool)

	for k, entry := range reg {
		kClean := filepath.Clean(k)
		kEval, _ := filepath.EvalSymlinks(kClean)
		rootClean := filepath.Clean(entry.RootPath)
		rootEval, _ := filepath.EvalSymlinks(rootClean)

		matches := kClean == cleanRoot ||
			(evalRoot != "" && kClean == evalRoot) ||
			(kEval != "" && kEval == cleanRoot) ||
			(kEval != "" && evalRoot != "" && kEval == evalRoot) ||
			rootClean == cleanRoot ||
			(evalRoot != "" && rootClean == evalRoot) ||
			(rootEval != "" && rootEval == cleanRoot) ||
			(rootEval != "" && evalRoot != "" && rootEval == evalRoot)

		if matches {
			if entry.RepoID != "" && !seen[entry.RepoID] {
				seen[entry.RepoID] = true
				removedIDs = append(removedIDs, entry.RepoID)
			}
			delete(reg, k)
		}
	}

	if err := SaveRegistry(dataDir, reg); err != nil {
		return nil, err
	}

	return removedIDs, nil
}

// FindRegistryEntry looks up a workspace path in the registry.
// Returns (*RegistryEntry, true, nil) if found, (nil, false, nil) if not enrolled.
func FindRegistryEntry(dataDir, workspacePath string) (*RegistryEntry, bool, error) {
	reg, err := LoadRegistry(dataDir)
	if err != nil {
		return nil, false, err
	}

	cleanPath := filepath.Clean(workspacePath)

	// 1. Direct match
	if entry, ok := reg[cleanPath]; ok {
		return &entry, true, nil
	}

	// 2. Symlink-evaluated match
	evalPath, err := filepath.EvalSymlinks(cleanPath)
	if err == nil && evalPath != cleanPath {
		if entry, ok := reg[evalPath]; ok {
			return &entry, true, nil
		}
	}

	// 3. Subdirectory match (workspace is inside an enrolled repository root/worktree)
	for regPath, entry := range reg {
		if isSubdir(cleanPath, regPath) {
			return &entry, true, nil
		}
		if evalPath != "" && isSubdir(evalPath, regPath) {
			return &entry, true, nil
		}
	}

	return nil, false, nil
}

func isSubdir(child, parent string) bool {
	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}
	return rel != "." && !strings.HasPrefix(rel, "..") && !strings.HasPrefix(rel, "/") && !strings.HasPrefix(rel, `\`)
}

